namespace nlohmann {
template <>
struct adl_serializer<std::variant<bool, double, int64_t, std::string>> {
    static void from_json(const json & j, std::variant<bool, double, int64_t, std::string> & x);
    static void to_json(json & j, const std::variant<bool, double, int64_t, std::string> & x);
};

template <>
struct adl_serializer<std::variant<int64_t, std::string>> {
    static void from_json(const json & j, std::variant<int64_t, std::string> & x);
    static void to_json(json & j, const std::variant<int64_t, std::string> & x);
};

template <>
struct adl_serializer<std::variant<std::vector<std::string>, int64_t>> {
    static void from_json(const json & j, std::variant<std::vector<std::string>, int64_t> & x);
    static void to_json(json & j, const std::variant<std::vector<std::string>, int64_t> & x);
};
}
namespace quicktype {
    inline void from_json(const json & j, Node& x) {
        if (!j.is_object()) throw std::runtime_error("Expected object");
        if (j.find("children") != j.end() && j.at("children").is_null()) throw std::runtime_error("Unexpected null");
        x.set_children(get_stack_optional<std::vector<Node>>(j, "children"));
        if (j.find("next") != j.end() && j.at("next").is_null()) throw std::runtime_error("Unexpected null");
        x.set_next(get_heap_optional<Node>(j, "next"));
        x.set_value(j.at("value").get<std::string>());
    }

    inline void to_json(json & j, const Node & x) {
        j = json::object();
        j["children"] = x.get_children();
        j["next"] = x.get_next();
        j["value"] = x.get_value();
    }

    inline void from_json(const json & j, Holder& x) {
        if (!j.is_object()) throw std::runtime_error("Expected object");
        if (j.find("items") != j.end() && j.at("items").is_null()) throw std::runtime_error("Unexpected null");
        x.set_items(get_stack_optional<std::vector<Node>>(j, "items"));
    }

    inline void to_json(json & j, const Holder & x) {
        j = json::object();
        j["items"] = x.get_items();
    }

    inline void from_json(const json & j, Pointer& x) {
        if (!j.is_object()) throw std::runtime_error("Expected object");
        j.at("target");
        x.set_target(get_heap_optional<Node>(j, "target"));
    }

    inline void to_json(json & j, const Pointer & x) {
        j = json::object();
        j["target"] = x.get_target();
    }

    inline void from_json(const json & j, TopLevel& x) {
        if (!j.is_object()) throw std::runtime_error("Expected object");
        x.set_anything(get_untyped(j, "anything"));
        x.set_big_kind(j.at("bigKind").get<BigKind>());
        x.set_choice(j.at("choice").get<ChoiceUnion>());
        x.set_counts(j.at("counts").get<std::map<std::string, int64_t>>());
        x.set_flag(j.at("flag").get<bool>());
        if (j.find("holder") != j.end() && j.at("holder").is_null()) throw std::runtime_error("Unexpected null");
        x.set_holder(get_stack_optional<Holder>(j, "holder"));
        if (j.find("id") != j.end() && !std::regex_match(j.at("id").get<std::string>(), std::regex("^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"))) throw std::runtime_error("Expected UUID");
        x.set_id(j.at("id").get<std::string>());
        x.set_kind(j.at("kind").get<Kind>());
        j.at("maybeChoice");
        x.set_maybe_choice(get_stack_optional<std::variant<int64_t, std::string>>(j, "maybeChoice"));
        j.at("maybeKind");
        x.set_maybe_kind(get_stack_optional<MaybeKind>(j, "maybeKind"));
        j.at("maybeSmall");
        x.set_maybe_small(get_stack_optional<int64_t>(j, "maybeSmall"));
        x.set_mixed_map(j.at("mixedMap").get<std::map<std::string, MixedMap>>());
        x.set_name(j.at("name").get<std::string>());
        x.set_node(j.at("node").get<Node>());
        x.set_nothing(get_untyped(j, "nothing"));
        if (j.find(([] { constexpr auto &s = "nul\u0000key"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())) != j.end() && !j.at(([] { constexpr auto &s = "nul\u0000key"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())).is_number_integer()) throw std::runtime_error("Expected integer");
        x.set_nul_key(j.at(([] { constexpr auto &s = "nul\u0000key"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())).get<int64_t>());
        x.set_opt_anything(get_untyped(j, "optAnything"));
        if (j.find("optName") != j.end() && j.at("optName").is_null()) throw std::runtime_error("Unexpected null");
        x.set_opt_name(get_stack_optional<std::string>(j, "optName"));
        if (j.find("optNode") != j.end() && j.at("optNode").is_null()) throw std::runtime_error("Unexpected null");
        x.set_opt_node(get_heap_optional<Node>(j, "optNode"));
        x.set_opt_nothing(get_untyped(j, "optNothing"));
        if (j.find("optWhen") != j.end() && !std::regex_match(j.at("optWhen").get<std::string>(), std::regex("^[0-9]{4}-[0-9]{2}-[0-9]{2}T.*$"))) throw std::runtime_error("Expected date-time");
        if (j.find("optWhen") != j.end() && j.at("optWhen").is_null()) throw std::runtime_error("Unexpected null");
        x.set_opt_when(get_stack_optional<std::string>(j, "optWhen"));
        if (j.find("pointer") != j.end() && j.at("pointer").is_null()) throw std::runtime_error("Unexpected null");
        x.set_pointer(get_stack_optional<Pointer>(j, "pointer"));
        x.set_ratio(j.at("ratio").get<double>());
        if (j.find("shared") != j.end() && j.at("shared").is_null()) throw std::runtime_error("Unexpected null");
        x.set_shared(get_heap_optional<Node>(j, "shared"));
        if (j.find("small") != j.end() && !j.at("small").is_number_integer()) throw std::runtime_error("Expected integer");
        x.set_small(j.at("small").get<int64_t>());
        if (j.at("tags").size() < 1) throw std::runtime_error("Too few items");
        if (j.at("tags").size() > 4) throw std::runtime_error("Too many items");
        x.set_tags(j.at("tags").get<std::vector<std::string>>());
        if (j.find("when") != j.end() && !std::regex_match(j.at("when").get<std::string>(), std::regex("^[0-9]{4}-[0-9]{2}-[0-9]{2}T.*$"))) throw std::runtime_error("Expected date-time");
        x.set_when(j.at("when").get<std::string>());
    }

    inline void to_json(json & j, const TopLevel & x) {
        j = json::object();
        j["anything"] = x.get_anything();
        j["bigKind"] = x.get_big_kind();
        j["choice"] = x.get_choice();
        j["counts"] = x.get_counts();
        j["flag"] = x.get_flag();
        j["holder"] = x.get_holder();
        j["id"] = x.get_id();
        j["kind"] = x.get_kind();
        j["maybeChoice"] = x.get_maybe_choice();
        j["maybeKind"] = x.get_maybe_kind();
        j["maybeSmall"] = x.get_maybe_small();
        j["mixedMap"] = x.get_mixed_map();
        j["name"] = x.get_name();
        j["node"] = x.get_node();
        j["nothing"] = x.get_nothing();
        j[([] { constexpr auto &s = "nul\u0000key"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())] = x.get_nul_key();
        j["optAnything"] = x.get_opt_anything();
        j["optName"] = x.get_opt_name();
        j["optNode"] = x.get_opt_node();
        j["optNothing"] = x.get_opt_nothing();
        j["optWhen"] = x.get_opt_when();
        j["pointer"] = x.get_pointer();
        j["ratio"] = x.get_ratio();
        j["shared"] = x.get_shared();
        j["small"] = x.get_small();
        j["tags"] = x.get_tags();
        j["when"] = x.get_when();
    }

    inline void from_json(const json & j, BigKind & x) {
        static std::unordered_map<std::string, BigKind> enumValues {
            {"c0", BigKind::C0},
            {"c1", BigKind::C1},
            {"c2", BigKind::C2},
            {"c3", BigKind::C3},
            {"c4", BigKind::C4},
            {"c5", BigKind::C5},
            {"c6", BigKind::C6},
            {"c7", BigKind::C7},
            {"c8", BigKind::C8},
            {"c9", BigKind::C9},
            {"c10", BigKind::C10},
            {"c11", BigKind::C11},
            {"c12", BigKind::C12},
            {"c13", BigKind::C13},
            {"c14", BigKind::C14},
            {"c15", BigKind::C15},
            {"c16", BigKind::C16},
        };
        auto iter = enumValues.find(j.get<std::string>());
        if (iter != enumValues.end()) {
            x = iter->second;
        }
        else { throw std::runtime_error("Cannot deserialize to enumeration \"BigKind\""); }
    }

    inline void to_json(json & j, const BigKind & x) {
        switch (x) {
            case BigKind::C0: j = "c0"; break;
            case BigKind::C1: j = "c1"; break;
            case BigKind::C2: j = "c2"; break;
            case BigKind::C3: j = "c3"; break;
            case BigKind::C4: j = "c4"; break;
            case BigKind::C5: j = "c5"; break;
            case BigKind::C6: j = "c6"; break;
            case BigKind::C7: j = "c7"; break;
            case BigKind::C8: j = "c8"; break;
            case BigKind::C9: j = "c9"; break;
            case BigKind::C10: j = "c10"; break;
            case BigKind::C11: j = "c11"; break;
            case BigKind::C12: j = "c12"; break;
            case BigKind::C13: j = "c13"; break;
            case BigKind::C14: j = "c14"; break;
            case BigKind::C15: j = "c15"; break;
            case BigKind::C16: j = "c16"; break;
            default: throw std::runtime_error("Unexpected value in enumeration \"BigKind\": " + std::to_string(static_cast<int>(x)));
        }
    }

    inline void from_json(const json & j, Kind & x) {
        if (j == "one") x = Kind::ONE;
        else if (j == "two") x = Kind::TWO;
        else if (j == ([] { constexpr auto &s = "nul\u0000"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())) x = Kind::NUL;
        else { throw std::runtime_error("Cannot deserialize to enumeration \"Kind\""); }
    }

    inline void to_json(json & j, const Kind & x) {
        switch (x) {
            case Kind::ONE: j = "one"; break;
            case Kind::TWO: j = "two"; break;
            case Kind::NUL: j = ([] { constexpr auto &s = "nul\u0000"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }()); break;
            default: throw std::runtime_error("Unexpected value in enumeration \"Kind\": " + std::to_string(static_cast<int>(x)));
        }
    }

    inline void from_json(const json & j, MaybeKind & x) {
        if (j == "a") x = MaybeKind::A;
        else if (j == "b") x = MaybeKind::B;
        else { throw std::runtime_error("Cannot deserialize to enumeration \"MaybeKind\""); }
    }

    inline void to_json(json & j, const MaybeKind & x) {
        switch (x) {
            case MaybeKind::A: j = "a"; break;
            case MaybeKind::B: j = "b"; break;
            default: throw std::runtime_error("Unexpected value in enumeration \"MaybeKind\": " + std::to_string(static_cast<int>(x)));
        }
    }
}
namespace nlohmann {
    inline void adl_serializer<std::variant<bool, double, int64_t, std::string>>::from_json(const json & j, std::variant<bool, double, int64_t, std::string> & x) {
        if (j.is_boolean())
            x = j.get<bool>();
        else if (j.is_number_integer())
            x = j.get<int64_t>();
        else if (j.is_number())
            x = j.get<double>();
        else if (j.is_string())
            x = j.get<std::string>();
        else throw std::runtime_error("Could not deserialise!");
    }

    inline void adl_serializer<std::variant<bool, double, int64_t, std::string>>::to_json(json & j, const std::variant<bool, double, int64_t, std::string> & x) {
        switch (x.index()) {
            case 0:
                j = std::get<bool>(x);
                break;
            case 1:
                j = std::get<double>(x);
                break;
            case 2:
                j = std::get<int64_t>(x);
                break;
            case 3:
                j = std::get<std::string>(x);
                break;
            default: throw std::runtime_error("Input JSON does not conform to schema!");
        }
    }

    inline void adl_serializer<std::variant<int64_t, std::string>>::from_json(const json & j, std::variant<int64_t, std::string> & x) {
        if (j.is_number_integer())
            x = j.get<int64_t>();
        else if (j.is_string())
            x = j.get<std::string>();
        else throw std::runtime_error("Could not deserialise!");
    }

