    inline void from_json(const json & j, TopLevel& x) {
        if (!j.is_object()) throw std::runtime_error("Expected object");
        x.set_anything(get_untyped(j, Utf16_Utf8<std::wstring, std::string>::convert(L"anything")));
        x.set_big_kind(j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"bigKind")).get<BigKind>());
        x.set_choice(j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"choice")).get<ChoiceUnion>());
        x.set_counts(Utf16_Utf8<std::map<std::string, int64_t>, std::map<std::wstring, int64_t>>::convert(j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"counts")).get<std::map<std::string, int64_t>>()));
        x.set_flag(j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"flag")).get<bool>());
        if (j.find("holder") != j.end() && j.at("holder").is_null()) throw std::runtime_error("Unexpected null");
        x.set_holder(get_stack_optional<Holder>(j, Utf16_Utf8<std::wstring, std::string>::convert(L"holder")));
        if (j.find("id") != j.end() && !std::regex_match(j.at("id").get<std::string>(), std::regex("^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"))) throw std::runtime_error("Expected UUID");
        x.set_id(j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"id")).get<std::wstring>());
        x.set_kind(j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"kind")).get<Kind>());
        j.at("maybeChoice");
        x.set_maybe_choice(get_stack_optional<boost::variant<int64_t, std::wstring>>(j, Utf16_Utf8<std::wstring, std::string>::convert(L"maybeChoice")));
        j.at("maybeKind");
        x.set_maybe_kind(get_stack_optional<MaybeKind>(j, Utf16_Utf8<std::wstring, std::string>::convert(L"maybeKind")));
        j.at("maybeSmall");
        x.set_maybe_small(get_stack_optional<int64_t>(j, Utf16_Utf8<std::wstring, std::string>::convert(L"maybeSmall")));
        x.set_mixed_map(Utf16_Utf8<std::map<std::string, MixedMap>, std::map<std::wstring, MixedMap>>::convert(j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"mixedMap")).get<std::map<std::string, MixedMap>>()));
        x.set_name(Utf16_Utf8<std::string, std::wstring>::convert(j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"name")).get<std::string>()));
        x.set_node(j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"node")).get<Node>());
        x.set_nothing(get_untyped(j, Utf16_Utf8<std::wstring, std::string>::convert(L"nothing")));
        if (j.find(([] { constexpr auto &s = "nul\u0000key"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())) != j.end() && !j.at(([] { constexpr auto &s = "nul\u0000key"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())).is_number_integer()) throw std::runtime_error("Expected integer");
        x.set_nul_key(j.at(Utf16_Utf8<std::wstring, std::string>::convert(([] { constexpr auto &s = L"nul\u0000key"; return std::wstring(s, sizeof(s) / sizeof(s[0]) - 1); }()))).get<int64_t>());
        x.set_opt_anything(get_untyped(j, Utf16_Utf8<std::wstring, std::string>::convert(L"optAnything")));
        if (j.find("optName") != j.end() && j.at("optName").is_null()) throw std::runtime_error("Unexpected null");
        x.set_opt_name(Utf16_Utf8<boost::optional<std::string>, boost::optional<std::wstring>>::convert(get_stack_optional<std::string>(j, Utf16_Utf8<std::wstring, std::string>::convert(L"optName"))));
        if (j.find("optNode") != j.end() && j.at("optNode").is_null()) throw std::runtime_error("Unexpected null");
        x.set_opt_node(get_heap_optional<Node>(j, Utf16_Utf8<std::wstring, std::string>::convert(L"optNode")));
        x.set_opt_nothing(get_untyped(j, Utf16_Utf8<std::wstring, std::string>::convert(L"optNothing")));
        if (j.find("optWhen") != j.end() && !std::regex_match(j.at("optWhen").get<std::string>(), std::regex("^[0-9]{4}-[0-9]{2}-[0-9]{2}T.*$"))) throw std::runtime_error("Expected date-time");
        if (j.find("optWhen") != j.end() && j.at("optWhen").is_null()) throw std::runtime_error("Unexpected null");
        x.set_opt_when(get_stack_optional<std::wstring>(j, Utf16_Utf8<std::wstring, std::string>::convert(L"optWhen")));
        if (j.find("pointer") != j.end() && j.at("pointer").is_null()) throw std::runtime_error("Unexpected null");
        x.set_pointer(get_stack_optional<Pointer>(j, Utf16_Utf8<std::wstring, std::string>::convert(L"pointer")));
        x.set_ratio(j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"ratio")).get<double>());
        if (j.find("shared") != j.end() && j.at("shared").is_null()) throw std::runtime_error("Unexpected null");
        x.set_shared(get_heap_optional<Node>(j, Utf16_Utf8<std::wstring, std::string>::convert(L"shared")));
        if (j.find("small") != j.end() && !j.at("small").is_number_integer()) throw std::runtime_error("Expected integer");
        x.set_small(j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"small")).get<int64_t>());
        if (j.at("tags").size() < 1) throw std::runtime_error("Too few items");
        if (j.at("tags").size() > 4) throw std::runtime_error("Too many items");
        x.set_tags(Utf16_Utf8<std::vector<std::string>, std::vector<std::wstring>>::convert(j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"tags")).get<std::vector<std::string>>()));
        if (j.find("when") != j.end() && !std::regex_match(j.at("when").get<std::string>(), std::regex("^[0-9]{4}-[0-9]{2}-[0-9]{2}T.*$"))) throw std::runtime_error("Expected date-time");
        x.set_when(j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"when")).get<std::wstring>());
    }

